SELECT 
FROM yms_internal_task t
WHERE t.deleted = 0

      AND t.warehouse_id = #{bo.warehouseId}


      AND t.internal_task_type = #{bo.internalTaskType}


      AND t.task_status = #{bo.taskStatus}


      AND t.object_no LIKE CONCAT('%', #{bo.objectNo}, '%')


      AND t.executor_name LIKE CONCAT('%', #{bo.executorName}, '%')


      AND t.parent_yard_task_id = #{bo.parentYardTaskId}

ORDER BY t.priority ASC, t.create_time DESC

SELECT FROM yms_internal_task t WHERE t.deleted = 0 AND t.task_status NOT IN ('COMPLETED', 'CANCELLED')
AND t.warehouse_id = #{warehouseId}
AND t.internal_task_type = #{internalTaskType}
ORDER BY t.priority ASC, t.create_time ASC
